/* ==========================================================================
   DUNGEON HAUL — Official Promotional Website Design System
   Visual Aesthetics: Retro Pixel Arcade / Deep Dungeon Vault / Glassmorphic Gold
   ========================================================================== */

@import url('https://fonts.googleapis.com/css2?family=Cinzel:wght@600;800;900&family=Inter:wght@400;500;600;700;800&family=Press+Start+2P&display=swap');

:root {
  /* Core Dungeon Colors */
  --bg-dark: #090712;
  --bg-surface: #141026;
  --bg-card: rgba(26, 21, 48, 0.85);
  --bg-card-hover: rgba(38, 31, 70, 0.95);
  --border-gold: #d4a017;
  --border-muted: rgba(212, 160, 23, 0.25);

  /* Gold & Accents */
  --gold-primary: #f3c032;
  --gold-light: #ffe28a;
  --gold-dark: #b8860b;
  --gold-glow: rgba(243, 192, 50, 0.35);

  /* Hauler Seat Identities */
  --hauler-gnome: #f0a040;
  --hauler-gnome-glow: rgba(240, 160, 64, 0.4);
  --hauler-sprite: #50a0e8;
  --hauler-sprite-glow: rgba(80, 160, 232, 0.4);
  --hauler-halfling: #e070b0;
  --hauler-halfling-glow: rgba(224, 112, 176, 0.4);
  --hauler-dwarf: #e05040;
  --hauler-dwarf-glow: rgba(224, 80, 64, 0.4);

  /* Functional / Status Colors */
  --color-success: #40e0a0;
  --color-danger: #ff5040;
  --color-penalty-blue: #3a6bc4;
  --text-main: #f4efe4;
  --text-muted: #a8a3c1;
  --text-dim: #6e698b;

  /* Fonts */
  --font-pixel: 'Press Start 2P', monospace;
  --font-heading: 'Cinzel', serif;
  --font-body: 'Inter', sans-serif;

  /* Layout */
  --max-width: 1200px;
  --radius-sm: 6px;
  --radius-md: 12px;
  --radius-lg: 20px;
  --transition: all 0.25s cubic-bezier(0.16, 1, 0.3, 1);
}

/* Reset & Base Setup */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  font-size: 16px;
  background-color: var(--bg-dark);
  color: var(--text-main);
  font-family: var(--font-body);
  line-height: 1.6;
}

body {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  background: 
    radial-gradient(circle at 50% 0%, rgba(243, 192, 50, 0.08) 0%, transparent 60%),
    radial-gradient(circle at 80% 40%, rgba(80, 160, 232, 0.05) 0%, transparent 50%),
    radial-gradient(circle at 20% 80%, rgba(224, 80, 64, 0.05) 0%, transparent 50%),
    var(--bg-dark);
  background-attachment: fixed;
  overflow-x: hidden;
}

/* Typography Utility */
h1, h2, h3, h4 {
  color: var(--text-main);
  font-family: var(--font-heading);
  font-weight: 800;
  line-height: 1.2;
  letter-spacing: 0.02em;
}

.pixel-text {
  font-family: var(--font-pixel);
  letter-spacing: -0.05em;
}

.gold-gradient-text {
  background: linear-gradient(135deg, var(--gold-light) 0%, var(--gold-primary) 50%, var(--gold-dark) 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

/* Navigation Bar */
.navbar {
  position: sticky;
  top: 0;
  z-index: 1000;
  background: rgba(9, 7, 18, 0.88);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border-bottom: 2px solid var(--border-muted);
  transition: var(--transition);
}

.navbar-container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 1rem 1.5rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.brand-logo {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  text-decoration: none;
}

.brand-icon {
  width: 40px;
  height: 40px;
  background: linear-gradient(135deg, var(--gold-primary), var(--gold-dark));
  border-radius: var(--radius-sm);
  display: grid;
  place-items: center;
  font-family: var(--font-pixel);
  font-size: 0.8rem;
  color: var(--bg-dark);
  box-shadow: 0 0 12px var(--gold-glow);
  transform: rotate(-3deg);
  transition: var(--transition);
}

.brand-logo:hover .brand-icon {
  transform: rotate(0deg) scale(1.08);
}

.brand-title {
  font-family: var(--font-pixel);
  font-size: 1.1rem;
  color: var(--gold-primary);
  text-shadow: 2px 2px 0px #000;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 2rem;
  list-style: none;
}

.nav-link {
  color: var(--text-muted);
  text-decoration: none;
  font-weight: 600;
  font-size: 0.95rem;
  transition: var(--transition);
  position: relative;
  padding: 0.4rem 0;
}

.nav-link::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 0%;
  height: 2px;
  background: var(--gold-primary);
  box-shadow: 0 0 8px var(--gold-primary);
  transition: var(--transition);
}

.nav-link:hover, .nav-link.active {
  color: var(--gold-light);
}

.nav-link:hover::after, .nav-link.active::after {
  width: 100%;
}

.btn-play-nav {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  background: linear-gradient(135deg, var(--gold-primary) 0%, var(--gold-dark) 100%);
  color: var(--bg-dark);
  font-family: var(--font-pixel);
  font-size: 0.7rem;
  padding: 0.75rem 1.25rem;
  border-radius: var(--radius-sm);
  text-decoration: none;
  font-weight: bold;
  box-shadow: 0 0 15px var(--gold-glow);
  border: 2px solid var(--gold-light);
  transition: var(--transition);
}

.btn-play-nav:hover {
  transform: translateY(-2px);
  box-shadow: 0 0 22px rgba(243, 192, 50, 0.6);
  background: linear-gradient(135deg, var(--gold-light) 0%, var(--gold-primary) 100%);
}

.nav-toggle {
  display: none;
  background: none;
  border: none;
  color: var(--text-main);
  font-size: 1.5rem;
  cursor: pointer;
}

/* Layout Containers */
.main-content {
  flex: 1;
}

.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 3rem 1.5rem;
}

/* Hero Section */
.hero {
  position: relative;
  padding: 5rem 1.5rem 6rem;
  text-align: center;
  background: 
    linear-gradient(180deg, rgba(9, 7, 18, 0.4) 0%, rgba(9, 7, 18, 0.95) 100%),
    url('../images/bg_title.webp') center/cover no-repeat;
  border-bottom: 2px solid var(--border-muted);
}

.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.4rem 1rem;
  background: rgba(243, 192, 50, 0.12);
  border: 1px solid var(--border-gold);
  border-radius: 50px;
  font-family: var(--font-pixel);
  font-size: 0.75rem;
  color: var(--gold-light);
  margin-bottom: 1.5rem;
}

.hero-title {
  font-size: clamp(2.5rem, 6vw, 4.5rem);
  font-family: var(--font-heading);
  text-transform: uppercase;
  margin-bottom: 1rem;
  text-shadow: 0 0 30px rgba(243, 192, 50, 0.3);
}

.hero-subtitle {
  font-size: clamp(1.1rem, 2.5vw, 1.4rem);
  color: var(--text-muted);
  max-width: 750px;
  margin: 0 auto 2.5rem;
}

.hero-cta-group {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1.25rem;
  flex-wrap: wrap;
}

.btn-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.75rem;
  padding: 1rem 2rem;
  background: linear-gradient(135deg, var(--gold-primary) 0%, var(--gold-dark) 100%);
  color: var(--bg-dark);
  font-family: var(--font-pixel);
  font-size: 0.85rem;
  text-decoration: none;
  border-radius: var(--radius-sm);
  box-shadow: 0 0 20px var(--gold-glow);
  border: 2px solid var(--gold-light);
  cursor: pointer;
  transition: var(--transition);
}

.btn-primary:hover {
  transform: translateY(-3px) scale(1.02);
  box-shadow: 0 0 30px rgba(243, 192, 50, 0.7);
}

.btn-secondary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.75rem;
  padding: 1rem 2rem;
  background: rgba(20, 16, 38, 0.8);
  color: var(--text-main);
  font-family: var(--font-pixel);
  font-size: 0.85rem;
  text-decoration: none;
  border-radius: var(--radius-sm);
  border: 2px solid var(--border-gold);
  cursor: pointer;
  transition: var(--transition);
}

.btn-secondary:hover {
  background: rgba(243, 192, 50, 0.15);
  color: var(--gold-light);
  transform: translateY(-3px);
}

/* Feature Grid Cards */
.section-header {
  text-align: center;
  margin-bottom: 3.5rem;
}

.section-tag {
  font-family: var(--font-pixel);
  font-size: 0.75rem;
  color: var(--gold-primary);
  text-transform: uppercase;
  letter-spacing: 0.1em;
  margin-bottom: 0.75rem;
  display: block;
}

.section-title {
  font-size: clamp(2rem, 4vw, 3rem);
  margin-bottom: 1rem;
}

.section-desc {
  color: var(--text-muted);
  max-width: 650px;
  margin: 0 auto;
  font-size: 1.1rem;
}

.feature-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 2rem;
}

.feature-card {
  background: var(--bg-card);
  border: 1px solid var(--border-muted);
  border-radius: var(--radius-md);
  padding: 2.25rem;
  transition: var(--transition);
  position: relative;
  overflow: hidden;
}

.feature-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 3px;
  background: linear-gradient(90deg, transparent, var(--gold-primary), transparent);
  opacity: 0;
  transition: var(--transition);
}

.feature-card:hover {
  transform: translateY(-6px);
  background: var(--bg-card-hover);
  border-color: var(--border-gold);
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.4), 0 0 15px var(--gold-glow);
}

.feature-card:hover::before {
  opacity: 1;
}

.feature-icon-wrapper {
  width: 60px;
  height: 60px;
  background: rgba(243, 192, 50, 0.1);
  border: 1px solid var(--border-gold);
  border-radius: var(--radius-sm);
  display: grid;
  place-items: center;
  font-size: 1.75rem;
  color: var(--gold-primary);
  margin-bottom: 1.5rem;
}

.feature-card-title {
  font-size: 1.4rem;
  margin-bottom: 0.75rem;
}

.feature-card-desc {
  color: var(--text-muted);
  font-size: 0.95rem;
}

/* Screenshot Showcase / Gallery Carousel */
.showcase-section {
  background: rgba(13, 10, 24, 0.6);
  border-top: 1px solid var(--border-muted);
  border-bottom: 1px solid var(--border-muted);
  padding: 4rem 0;
}

.showcase-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
  gap: 1.5rem;
  margin-top: 2rem;
}

.showcase-item {
  position: relative;
  border-radius: var(--radius-md);
  overflow: hidden;
  border: 2px solid var(--border-muted);
  aspect-ratio: 16 / 9;
  background: var(--bg-dark);
  cursor: pointer;
  transition: var(--transition);
}

.showcase-item img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.5s ease;
}

.showcase-item:hover {
  border-color: var(--gold-primary);
  box-shadow: 0 0 25px var(--gold-glow);
}

.showcase-item:hover img {
  transform: scale(1.06);
}

.showcase-caption {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  padding: 1.25rem;
  background: linear-gradient(0deg, rgba(9, 7, 18, 0.95) 0%, rgba(9, 7, 18, 0) 100%);
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
}

.showcase-caption-text {
  font-family: var(--font-pixel);
  font-size: 0.75rem;
  color: var(--gold-light);
  text-shadow: 1px 1px 2px #000;
}

/* Character Showcase Page */
.char-hero-card {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 3rem;
  background: var(--bg-card);
  border: 2px solid var(--border-gold);
  border-radius: var(--radius-lg);
  padding: 3rem;
  align-items: center;
  box-shadow: 0 0 40px rgba(0, 0, 0, 0.5);
  margin-bottom: 4rem;
}

.char-nav-tabs {
  display: flex;
  justify-content: center;
  gap: 1rem;
  margin-bottom: 2.5rem;
  flex-wrap: wrap;
}

.char-tab-btn {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.85rem 1.5rem;
  background: var(--bg-card);
  border: 2px solid var(--border-muted);
  border-radius: var(--radius-sm);
  color: var(--text-muted);
  font-family: var(--font-pixel);
  font-size: 0.75rem;
  cursor: pointer;
  transition: var(--transition);
}

.char-tab-btn[data-char="gnome"].active {
  border-color: var(--hauler-gnome);
  color: var(--hauler-gnome);
  box-shadow: 0 0 15px var(--hauler-gnome-glow);
  background: rgba(240, 160, 64, 0.12);
}

.char-tab-btn[data-char="sprite"].active {
  border-color: var(--hauler-sprite);
  color: var(--hauler-sprite);
  box-shadow: 0 0 15px var(--hauler-sprite-glow);
  background: rgba(80, 160, 232, 0.12);
}

.char-tab-btn[data-char="halfling"].active {
  border-color: var(--hauler-halfling);
  color: var(--hauler-halfling);
  box-shadow: 0 0 15px var(--hauler-halfling-glow);
  background: rgba(224, 112, 176, 0.12);
}

.char-tab-btn[data-char="dwarf"].active {
  border-color: var(--hauler-dwarf);
  color: var(--hauler-dwarf);
  box-shadow: 0 0 15px var(--hauler-dwarf-glow);
  background: rgba(224, 80, 64, 0.12);
}

.char-avatar-frame {
  position: relative;
  border-radius: var(--radius-md);
  overflow: hidden;
  border: 3px solid var(--border-gold);
  background: #000;
  aspect-ratio: 1 / 1;
  display: flex;
  align-items: center;
  justify-content: center;
}

.char-avatar-frame img {
  width: 100%;
  height: 100%;
  object-fit: contain;
  padding: 1rem;
}

.char-badge {
  display: inline-block;
  padding: 0.25rem 0.75rem;
  border-radius: 4px;
  font-family: var(--font-pixel);
  font-size: 0.65rem;
  text-transform: uppercase;
  margin-bottom: 1rem;
}

.char-badge.gnome { background: var(--hauler-gnome); color: #000; }
.char-badge.sprite { background: var(--hauler-sprite); color: #000; }
.char-badge.halfling { background: var(--hauler-halfling); color: #000; }
.char-badge.dwarf { background: var(--hauler-dwarf); color: #000; }

.stat-bar-group {
  margin-top: 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.stat-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
}

.stat-label {
  font-family: var(--font-pixel);
  font-size: 0.65rem;
  color: var(--text-muted);
  width: 120px;
}

.stat-track {
  flex: 1;
  height: 10px;
  background: rgba(255, 255, 255, 0.1);
  border-radius: 5px;
  overflow: hidden;
  border: 1px solid var(--border-muted);
}

.stat-fill {
  height: 100%;
  border-radius: 5px;
  transition: width 0.6s cubic-bezier(0.16, 1, 0.3, 1);
}

/* Instructions / Rules Page */
.rules-container {
  display: grid;
  grid-template-columns: 280px 1fr;
  gap: 2.5rem;
}

.rules-sidebar {
  position: sticky;
  top: 100px;
  height: fit-content;
  background: var(--bg-card);
  border: 1px solid var(--border-muted);
  border-radius: var(--radius-md);
  padding: 1.5rem;
}

.rules-menu {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.rules-menu-link {
  display: block;
  padding: 0.75rem 1rem;
  color: var(--text-muted);
  text-decoration: none;
  border-radius: var(--radius-sm);
  font-size: 0.95rem;
  font-weight: 600;
  transition: var(--transition);
}

.rules-menu-link:hover, .rules-menu-link.active {
  background: rgba(243, 192, 50, 0.12);
  color: var(--gold-light);
  border-left: 3px solid var(--gold-primary);
}

.rules-content-block {
  background: var(--bg-card);
  border: 1px solid var(--border-muted);
  border-radius: var(--radius-md);
  padding: 2.5rem;
  margin-bottom: 2rem;
}

.rules-content-block h2 {
  font-size: 1.8rem;
  margin-bottom: 1.25rem;
  color: var(--gold-light);
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.controls-diagram-card {
  background: #000;
  border: 2px solid var(--border-gold);
  border-radius: var(--radius-md);
  padding: 2rem;
  text-align: center;
  margin: 1.5rem 0;
}

.controls-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 1.5rem;
  margin-top: 1.5rem;
}

.control-key-box {
  background: rgba(243, 192, 50, 0.08);
  border: 1px solid var(--border-gold);
  border-radius: var(--radius-sm);
  padding: 1.25rem;
}

.key-badge {
  display: inline-block;
  background: var(--gold-primary);
  color: var(--bg-dark);
  font-family: var(--font-pixel);
  font-size: 0.75rem;
  padding: 0.3rem 0.6rem;
  border-radius: 4px;
  font-weight: bold;
  margin-bottom: 0.5rem;
}

/* Modifiers Table */
.modifier-table {
  width: 100%;
  border-collapse: collapse;
  margin-top: 1.5rem;
}

.modifier-table th, .modifier-table td {
  padding: 0.9rem 1.2rem;
  text-align: left;
  border-bottom: 1px solid var(--border-muted);
}

.modifier-table th {
  font-family: var(--font-pixel);
  font-size: 0.7rem;
  color: var(--gold-primary);
  background: rgba(13, 10, 24, 0.8);
}

.tag-reward {
  color: var(--color-success);
  font-family: var(--font-pixel);
  font-size: 0.7rem;
}

.tag-penalty {
  color: var(--color-danger);
  font-family: var(--font-pixel);
  font-size: 0.7rem;
}

/* Play Arcade Container Page */
.arcade-wrapper {
  max-width: 1040px;
  margin: 0 auto;
  text-align: center;
}

.arcade-screen-container {
  position: relative;
  width: 100%;
  aspect-ratio: 16 / 9;
  background: #000;
  border: 4px solid var(--border-gold);
  border-radius: var(--radius-md);
  box-shadow: 0 0 50px rgba(243, 192, 50, 0.25), inset 0 0 30px rgba(0,0,0,0.8);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}

.arcade-canvas-placeholder {
  width: 100%;
  height: 100%;
  background: 
    linear-gradient(180deg, rgba(9, 7, 18, 0.7) 0%, rgba(9, 7, 18, 0.95) 100%),
    url('../images/bg_dungeon.webp') center/cover no-repeat;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 2rem;
  color: var(--text-main);
  position: relative;
}

.arcade-status-badge {
  background: var(--gold-primary);
  color: var(--bg-dark);
  font-family: var(--font-pixel);
  font-size: 0.8rem;
  padding: 0.5rem 1.25rem;
  border-radius: 50px;
  margin-bottom: 1.5rem;
  animation: pulse-glow 2s infinite alternate;
}

@keyframes pulse-glow {
  0% { box-shadow: 0 0 10px var(--gold-glow); }
  100% { box-shadow: 0 0 25px rgba(243, 192, 50, 0.9); }
}

.arcade-controls-bar {
  margin-top: 1.5rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: var(--bg-card);
  border: 1px solid var(--border-muted);
  border-radius: var(--radius-md);
  padding: 1.25rem 2rem;
  flex-wrap: wrap;
  gap: 1rem;
}

.room-code-input {
  background: #000;
  border: 1px solid var(--border-gold);
  color: var(--gold-light);
  font-family: var(--font-pixel);
  font-size: 0.9rem;
  padding: 0.6rem 1rem;
  border-radius: var(--radius-sm);
  width: 140px;
  text-align: center;
  text-transform: uppercase;
}

/* Credits Page */
.credits-card-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
  gap: 2.5rem;
  margin-top: 2rem;
}

.credit-card {
  background: var(--bg-card);
  border: 2px solid var(--border-gold);
  border-radius: var(--radius-lg);
  padding: 3rem 2rem;
  text-align: center;
  position: relative;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.4);
  transition: var(--transition);
}

.credit-card:hover {
  transform: translateY(-5px);
  box-shadow: 0 15px 40px var(--gold-glow);
}

.credit-avatar {
  width: 100px;
  height: 100px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--gold-primary), var(--gold-dark));
  border: 3px solid var(--gold-light);
  margin: 0 auto 1.5rem;
  display: grid;
  place-items: center;
  font-size: 2.5rem;
  box-shadow: 0 0 20px var(--gold-glow);
}

.credit-role {
  font-family: var(--font-pixel);
  font-size: 0.75rem;
  color: var(--gold-primary);
  text-transform: uppercase;
  margin-bottom: 0.5rem;
}

.credit-name {
  font-size: 1.8rem;
  margin-bottom: 1rem;
}

.credit-bio {
  color: var(--text-muted);
  font-size: 0.95rem;
}

/* Footer */
.footer {
  background: #06040c;
  border-top: 2px solid var(--border-muted);
  padding: 4rem 1.5rem 2rem;
  margin-top: auto;
}

.footer-container {
  max-width: var(--max-width);
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 3rem;
  margin-bottom: 3rem;
}

.footer-brand p {
  color: var(--text-muted);
  margin-top: 1rem;
  font-size: 0.9rem;
}

.footer-column-title {
  font-family: var(--font-pixel);
  font-size: 0.75rem;
  color: var(--gold-primary);
  margin-bottom: 1.25rem;
  text-transform: uppercase;
}

.footer-links {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.footer-links a {
  color: var(--text-muted);
  text-decoration: none;
  font-size: 0.9rem;
  transition: var(--transition);
}

.footer-links a:hover {
  color: var(--gold-light);
}

.footer-bottom {
  max-width: var(--max-width);
  margin: 0 auto;
  padding-top: 2rem;
  border-top: 1px solid var(--border-muted);
  display: flex;
  align-items: center;
  justify-content: space-between;
  color: var(--text-dim);
  font-size: 0.85rem;
  flex-wrap: wrap;
  gap: 1rem;
}

/* Lightbox Modal */
.modal-overlay {
  position: fixed;
  inset: 0;
  z-index: 2000;
  background: rgba(0, 0, 0, 0.9);
  backdrop-filter: blur(10px);
  display: none;
  place-items: center;
  padding: 2rem;
}

.modal-overlay.active {
  display: grid;
}

.modal-content-img {
  max-width: 90vw;
  max-height: 85vh;
  border: 3px solid var(--border-gold);
  border-radius: var(--radius-md);
  box-shadow: 0 0 50px var(--gold-glow);
}

.modal-close {
  position: absolute;
  top: 2rem;
  right: 2rem;
  background: var(--bg-card);
  border: 1px solid var(--border-gold);
  color: var(--gold-light);
  font-family: var(--font-pixel);
  font-size: 1.2rem;
  width: 44px;
  height: 44px;
  border-radius: 50%;
  cursor: pointer;
  display: grid;
  place-items: center;
}

/* Responsive Rules */
@media (max-width: 868px) {
  .nav-links {
    display: none;
    position: absolute;
    top: 100%;
    left: 0;
    right: 0;
    background: var(--bg-dark);
    border-bottom: 2px solid var(--border-muted);
    flex-direction: column;
    padding: 1.5rem;
    gap: 1rem;
  }

  .nav-links.active {
    display: flex;
  }

  .nav-toggle {
    display: block;
  }

  .char-hero-card {
    grid-template-columns: 1fr;
    padding: 1.75rem;
  }

  .rules-container {
    grid-template-columns: 1fr;
  }

  .rules-sidebar {
    position: relative;
    top: 0;
  }
}

/* ==========================================================================
   DUNGEON HAUL — Interactive Web Application Logic
   ========================================================================== */

document.addEventListener('DOMContentLoaded', () => {
  initMobileNav();
  initLightbox();
  initCharacterSwitcher();
  initArcadeSimulator();
  initRulesFilter();
});

/* Mobile Navigation Toggle */
function initMobileNav() {
  const toggle = document.querySelector('.nav-toggle');
  const links = document.querySelector('.nav-links');

  if (toggle && links) {
    toggle.addEventListener('click', () => {
      links.classList.toggle('active');
    });
  }
}

/* Lightbox Modal for Screenshots */
function initLightbox() {
  const showcaseItems = document.querySelectorAll('.showcase-item');

  if (showcaseItems.length === 0) return;

  // Create overlay modal dynamically
  const overlay = document.createElement('div');
  overlay.className = 'modal-overlay';
  overlay.innerHTML = `
    <button class="modal-close" aria-label="Close Preview">&times;</button>
    <img class="modal-content-img" src="" alt="Dungeon Haul Preview">
  `;
  document.body.appendChild(overlay);

  const modalImg = overlay.querySelector('.modal-content-img');
  const closeBtn = overlay.querySelector('.modal-close');

  showcaseItems.forEach(item => {
    item.addEventListener('click', () => {
      const img = item.querySelector('img');
      if (img) {
        modalImg.src = img.src;
        modalImg.alt = img.alt || 'Dungeon Haul Screenshot';
        overlay.classList.add('active');
      }
    });
  });

  const closeModal = () => overlay.classList.remove('active');
  closeBtn.addEventListener('click', closeModal);
  overlay.addEventListener('click', (e) => {
    if (e.target === overlay) closeModal();
  });
}

/* Character Tab Switcher & Data */
const CHARACTER_DATA = {
  gnome: {
    name: 'Gnome',
    title: 'The Crafty Tinkerer',
    badgeClass: 'gnome',
    color: '#F0A040',
    spriteImage: 'assets/images/gnome_sprite_sheet_1784605988611.jpg',
    backstory: `Originating from the lower mechanical gear-works of the ancient dungeon, the Gnome is quick-witted, agile, and obsessed with ancient relics. Standing low to the ground with a iconic pointed amber hat, they can slip right under swinging pendulum traps and snatch gold coins before larger rivals even notice!`,
    stats: {
      speed: 90,
      jump: 85,
      strength: 60,
      sabotage: 75
    },
    specialAbility: 'Low Profile — Lower collision height when crouching, perfect for dodging overhead lightning traps and sneaking into hoard vaults.'
  },
  sprite: {
    name: 'Sprite',
    title: 'The High-Flying Mischief',
    badgeClass: 'sprite',
    color: '#50A0E8',
    spriteImage: 'assets/images/sprite_character_sheet_1784606136069.jpg',
    backstory: `Born from celestial ether mist, the Sky Blue Sprite is a nimble creature with ethereal wing nubs. Sprites view dungeon crawling as a high-stakes sport. They love leap-frogging over lava pits, hovering above crumbling stone bridges, and tossing coin sacks over their friends' heads!`,
    stats: {
      speed: 95,
      jump: 95,
      strength: 50,
      sabotage: 80
    },
    specialAbility: 'Feather Lift — Exceptional airtime control allowing precision jumps across wide pit traps.'
  },
  halfling: {
    name: 'Halfling',
    title: 'The Unstoppable Collector',
    badgeClass: 'halfling',
    color: '#E070B0',
    spriteImage: 'assets/images/halfling_character_sheet_1784606150621.jpg',
    backstory: `Driven by pure gold lust and an unquenchable desire for complete treasure sets, the Halfling is the ultimate hoarder. Recognized by their pink tunic and curly hair, they carry double-stacked chests without flinching and will argue passionately during the Fork voting chamber to secure their preferred route!`,
    stats: {
      speed: 70,
      jump: 70,
      strength: 85,
      sabotage: 85
    },
    specialAbility: 'Master Carrier — Reduced speed penalty from heavy treasure stacks; immune to minor trips.'
  },
  dwarf: {
    name: 'Dwarf',
    title: 'The Heavy Hitter',
    badgeClass: 'dwarf',
    color: '#E05040',
    spriteImage: 'assets/images/dwarf_character_sheet_1784606165897.jpg',
    backstory: `Stout, broad-chested, and sporting a thick braided beard, the Crimson Dwarf is a powerhouse. Dwarves don't just dodge traps — they push rivals straight into them! If another hauler gets too greedy, the Dwarf delivers a devastating shoulder push to scatter their loot across the floor.`,
    stats: {
      speed: 65,
      jump: 65,
      strength: 100,
      sabotage: 95
    },
    specialAbility: 'Heavy Brawler — Maximized push and trip force, spilling rival carry stacks with ease.'
  }
};

function initCharacterSwitcher() {
  const tabs = document.querySelectorAll('.char-tab-btn');
  const nameEl = document.getElementById('char-name');
  const titleEl = document.getElementById('char-title');
  const badgeEl = document.getElementById('char-badge');
  const imgEl = document.getElementById('char-img');
  const backstoryEl = document.getElementById('char-backstory');
  const specialEl = document.getElementById('char-special');

  const speedFill = document.getElementById('stat-speed');
  const jumpFill = document.getElementById('stat-jump');
  const strengthFill = document.getElementById('stat-strength');
  const sabotageFill = document.getElementById('stat-sabotage');

  if (!tabs.length || !nameEl) return;

  function setCharacter(key) {
    const char = CHARACTER_DATA[key];
    if (!char) return;

    // Active state
    tabs.forEach(t => t.classList.remove('active'));
    document.querySelector(`.char-tab-btn[data-char="${key}"]`)?.classList.add('active');

    // Update content
    nameEl.textContent = char.name;
    titleEl.textContent = char.title;
    badgeEl.textContent = char.name;
    badgeEl.className = `char-badge ${char.badgeClass}`;
    imgEl.src = char.spriteImage;
    imgEl.alt = `${char.name} Character Sheet`;
    backstoryEl.textContent = char.backstory;
    specialEl.textContent = char.specialAbility;

    // Update stat bars with color match
    updateStatBar(speedFill, char.stats.speed, char.color);
    updateStatBar(jumpFill, char.stats.jump, char.color);
    updateStatBar(strengthFill, char.stats.strength, char.color);
    updateStatBar(sabotageFill, char.stats.sabotage, char.color);
  }

  function updateStatBar(el, val, color) {
    if (el) {
      el.style.width = `${val}%`;
      el.style.backgroundColor = color;
      el.style.boxShadow = `0 0 10px ${color}`;
    }
  }

  tabs.forEach(tab => {
    tab.addEventListener('click', () => {
      const charKey = tab.getAttribute('data-char');
      setCharacter(charKey);
    });
  });

  // Default to Gnome
  setCharacter('gnome');
}

/* Interactive Arcade & Seat Simulator on play.html */
function initArcadeSimulator() {
  const seatBtns = document.querySelectorAll('.seat-select-btn');
  const selectedSeatText = document.getElementById('selected-seat-name');
  const generateCodeBtn = document.getElementById('btn-gen-code');
  const roomCodeInput = document.getElementById('room-code-val');
  const readyBtn = document.getElementById('btn-arcade-ready');
  const statusBadge = document.getElementById('arcade-status');

  if (seatBtns.length > 0) {
    seatBtns.forEach(btn => {
      btn.addEventListener('click', () => {
        seatBtns.forEach(b => b.classList.remove('active'));
        btn.classList.add('active');
        const charName = btn.getAttribute('data-seat-char');
        if (selectedSeatText) selectedSeatText.textContent = charName;
      });
    });
  }

  if (generateCodeBtn && roomCodeInput) {
    generateCodeBtn.addEventListener('click', () => {
      const randomCode = 'DH-' + Math.floor(1000 + Math.random() * 9000);
      roomCodeInput.value = randomCode;
    });
  }

  if (readyBtn && statusBadge) {
    readyBtn.addEventListener('click', () => {
      if (readyBtn.textContent.includes('READY')) {
        readyBtn.textContent = 'TOGGLE UNREADY';
        statusBadge.textContent = 'SEAT READY • WAITING FOR HOST';
        statusBadge.style.background = '#40E0A0';
      } else {
        readyBtn.textContent = 'CLICK TO READY UP';
        statusBadge.textContent = 'PLACEHOLDER MODE • GAME LAUNCHING SOON';
        statusBadge.style.background = '#F3C032';
      }
    });
  }
}

/* Rules Search / Filter on instructions.html */
function initRulesFilter() {
  const searchInput = document.getElementById('modifier-search');
  const rows = document.querySelectorAll('.modifier-table tbody tr');

  if (searchInput && rows.length > 0) {
    searchInput.addEventListener('input', (e) => {
      const term = e.target.value.toLowerCase().trim();
      rows.forEach(row => {
        const text = row.textContent.toLowerCase();
        row.style.display = text.includes(term) ? '' : 'none';
      });
    });
  }
}

